            result?: components["schemas"]["DiagnosticResult"] | components["schemas"]["DiagramAsIsResult"] | components["schemas"]["UnderstandingResult"] | components["schemas"]["PresentationResult"] | components["schemas"]["TranslationResult"] | components["schemas"]["PolicyAnalysisResult"] | components["schemas"]["TranscriptionResult"] | components["schemas"]["PolicyDraftResult"] | components["schemas"]["PackageResult"] | components["schemas"]["ReusedResult"] | components["schemas"]["GenericResult"] | components["schemas"]["DocumentResult"];
